{"path": "assets/styles.css", "content": ":root {
  color-scheme: light;
  --bg: #f7f9fc;
  --surface: #ffffff;
  --surface-muted: #eef4f8;
  --ink: #17202a;
  --muted: #5d6d7e;
  --brand: #175676;
  --brand-strong: #0d3b52;
  --accent: #c2843b;
  --border: #d9e2ec;
  --shadow: 0 20px 60px rgba(23, 32, 42, 0.10);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  line-height: 1.65;
}

a {
  color: var(--brand);
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.18em;
}

a:hover,
a:focus {
  color: var(--brand-strong);
}

.skip-link {
  background: var(--brand-strong);
  color: #fff;
  left: 1rem;
  padding: 0.75rem 1rem;
  position: absolute;
  top: -5rem;
  z-index: 20;
}

.skip-link:focus {
  top: 1rem;
}

.container {
  width: min(1120px, calc(100% - 2rem));
  margin-inline: auto;
}

.site-header {
  background: rgba(255, 255, 255, 0.92);
  border-bottom: 1px solid var(--border);
  position: sticky;
  top: 0;
  z-index: 10;
  backdrop-filter: blur(14px);
}

.nav,
.footer-grid {
  align-items: center;
  display: flex;
  justify-content: space-between;
  gap: 1rem;
}

.nav {
  min-height: 72px;
}

.brand {
  color: var(--ink);
  font-size: 1.1rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-decoration: none;
}

.nav-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.85rem;
}

.nav-links a {
  border-radius: 999px;
  color: var(--muted);
  font-weight: 700;
  padding: 0.45rem 0.75rem;
  text-decoration: none;
}

.nav-links a:hover,
.nav-links a:focus,
.nav-links a[aria-current="page"] {
  background: var(--surface-muted);
  color: var(--brand-strong);
}

.hero,
.page-hero {
  background:
    radial-gradient(circle at top left, rgba(23, 86, 118, 0.18), transparent 34rem),
    linear-gradient(135deg, #ffffff 0%, #edf5f9 100%);
  border-bottom: 1px solid var(--border);
}

.hero {
  padding: 6rem 0;
}

.page-hero {
  padding: 4.5rem 0;
}

.hero-grid,
.two-column {
  display: grid;
  gap: 2rem;
  grid-template-columns: minmax(0, 1.45fr) minmax(280px, 0.85fr);
}

h1,
h2,
h3 {
  color: var(--ink);
  line-height: 1.15;
  margin: 0 0 0.75rem;
}

h1 {
  font-size: clamp(2.6rem, 8vw, 5rem);
  letter-spacing: -0.06em;
}

h2 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  letter-spacing: -0.035em;
}

h3 {
  font-size: 1.2rem;
}

p {
  margin: 0 0 1rem;
}

.lead {
  color: var(--brand-strong);
  font-size: clamp(1.2rem, 2.5vw, 1.55rem);
  font-weight: 650;
}

.eyebrow {
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 850;
  letter-spacing: 0.14em;
  margin-bottom: 0.8rem;
  text-transform: uppercase;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-top: 2rem;
}

.button {
  background: var(--brand);
  border: 1px solid var(--brand);
  border-radius: 999px;
  color: #fff;
  display: inline-flex;
  font-weight: 800;
  padding: 0.8rem 1.05rem;
  text-decoration: none;
}

.button:hover,
.button:focus {
  background: var(--brand-strong);
  color: #fff;
}

.button.secondary {
  background: transparent;
  color: var(--brand);
}

.profile-card,
.card,
.post-card,
.feature-article,
.timeline article,
.publication-list article {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 24px;
  box-shadow: var(--shadow);
}

.profile-card {
  align-self: start;
  padding: 2rem;
}

.avatar {
  align-items: center;
  background: linear-gradient(135deg, var(--brand), #5dade2);
  border-radius: 22px;
  color: #fff;
  display: flex;
  font-size: 2rem;
  font-weight: 900;
  height: 88px;
  justify-content: center;
  margin-bottom: 1.2rem;
  width: 88px;
}

.contact-list,
.clean-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.contact-list li,
.clean-list li {
  border-top: 1px solid var(--border);
  padding: 0.9rem 0;
}

.section {
  padding: 4.5rem 0;
}

.muted {
  background: var(--surface-muted);
  border-block: 1px solid var(--border);
}

.section-heading {
  max-width: 760px;
  margin-bottom: 1.8rem;
}

.card-grid {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.card,
.post-card,
.feature-article,
.timeline article,
.publication-list article {
  padding: 1.4rem;
}

.timeline {
  display: grid;
  gap: 1rem;
}

.publication-list {
  display: grid;
  gap: 1rem;
  list-style-position: inside;
  margin: 0;
  padding: 0;
}

.publication-list li::marker {
  color: var(--accent);
  font-weight: 900;
}

.meta {
  color: var(--muted);
  font-size: 0.95rem;
  font-weight: 650;
}

.post-list {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.post-card h3 a {
  color: var(--ink);
  text-decoration: none;
}

.post-card h3 a:hover,
.post-card h3 a:focus {
  color: var(--brand);
  text-decoration: underline;
}

.feature-article + .feature-article {
  margin-top: 1rem;
}

.site-footer {
  background: var(--brand-strong);
  color: rgba(255, 255, 255, 0.86);
  padding: 2rem 0;
}

.site-footer a {
  color: #fff;
}

@media (max-width: 860px) {
  .hero-grid,
  .two-column,
  .card-grid,
  .post-list {
    grid-template-columns: 1fr;
  }

  .nav,
  .footer-grid {
    align-items: flex-start;
    flex-direction: column;
  }

  .hero,
  .page-hero,
  .section {
    padding-block: 3rem;
  }
}
"}

